class CreateOrderAction
{
    public function handle(User $user, array $payload): Order
    {
        return DB::transaction(function () use ($user, $payload) {
            $order = Order::create([
                'user_id' => $user->id,
                'status' => 'pending',
                'total' => $payload['total'],
            ]);

            OrderItem::insert($this->mapItems($order, $payload['items']));

            return $order;
        });
    }
}

public function update(UpdatePostRequest $request, Post $post, UpdatePostAction $action)
{
    $this->authorize('update', $post);

    $post = $action->handle($post, $request->validated());

    return redirect()->route('posts.show', $post);
}

class SendInvoiceEmail implements ShouldQueue
{
    public function handle(): void
    {
        if ($this->invoice->sent_at) {
            return;
        }

        Mail::to($this->invoice->customer_email)->send(new InvoiceReadyMail($this->invoice));

        $this->invoice->forceFill(['sent_at' => now()])->save();
    }
}

Route::post('/webhooks/payment', PaymentWebhookController::class);

class PaymentWebhookController
{
    public function __invoke(Request $request)
    {
        WebhookCall::create([
            'provider' => 'payment-gateway',
            'payload' => $request->json()->all(),
        ]);

        ProcessPaymentWebhook::dispatch($request->json()->all());

        return response()->json(['received' => true]);
    }
}
